window.Site=(()=>{
'use strict';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({user:null,onboarded:false,plan:'Free',cycle:'monthly',projects:[{id:'rain',name:'雨停之前',desc:'都市情感 · 一次迟到七年的重逢',art:6,source:'script',mode:'studio',updated:'刚刚',assetIds:['linxia','chenxu','shop'],chapters:[{id:'ch1',title:'重逢的第七天',status:'制作中',seconds:48},{id:'ch2',title:'那封未寄出的信',status:'剧本草稿',seconds:0}]}],assets:[{id:'linxia',name:'林夏',type:'角色',art:1,version:2,desc:'深色长发、红围巾、米色风衣。温柔而克制。',locked:true},{id:'chenxu',name:'陈序',type:'角色',art:2,version:1,desc:'书店店主，棕色短发、灰蓝外套。',locked:true},{id:'shop',name:'慢日子书店',type:'场景',art:0,version:1,desc:'街角的旧书店，室内暖光与雨天橱窗。',locked:true},{id:'rain-style',name:'雨日手绘',type:'画风',art:7,version:1,desc:'低饱和灰蓝、水彩肌理、暖琥珀光。',locked:true},{id:'scarf',name:'林夏的红围巾',type:'服装',art:1,version:1,desc:'暗红羊毛围巾，保持颜色与长度一致。',locked:true},{id:'letter',name:'未寄出的信',type:'道具',art:3,version:1,desc:'泛黄信封，褶痕是连续剧情的一部分。',locked:true},{id:'voice',name:'林夏 · 温柔清澈',type:'声音',art:8,version:1,desc:'预置音色示意，无声音克隆。',locked:true}],results:{},tasks:[{id:'task-demo',title:'第 01 章稳定初稿',projectId:'rain',status:'完成',progress:100,cost:0,kind:'稳定动画',steps:['读取锁定分格','应用运镜和字幕','保存稳定底稿']},{id:'task-review',title:'镜头 09 · 角色一致性',projectId:'rain',status:'待确认',progress:100,cost:0,kind:'质量检查',steps:['对照角色参考','标记表情差异','等待人工确认']},{id:'task-failed',title:'镜头 06 · 增强候选',projectId:'rain',status:'失败',progress:65,cost:0,kind:'增强视频',steps:['参考已提交','供应商超时','稳定底稿已保留']}],exports:[{id:'export-demo',projectId:'rain',name:'雨停之前 · 条漫长图',kind:'PNG',status:'完成',size:'1080 px',date:'示例记录'}],shares:[],prefs:{studio:'一人故事工作室',language:'简体中文',notify:true},draft:{source:'script',mode:'studio'},pending:null});
let state=defaults();try{const saved=JSON.parse(localStorage.getItem('framein-site-v1'));if(saved)state={...state,...saved};}catch{}
let context={path:'/',parts:[],params:new URLSearchParams()},modalFocus=null,downloadPreviewURL=null;
const ui={toolGroup:'全部',toolQuery:'',projectQuery:'',assetType:'全部',assetQuery:'',templateType:'全部',caseType:'全部',resourceQuery:'',taskFilter:'全部',projectView:'grid'};
function save(){try{localStorage.setItem('framein-site-v1',JSON.stringify(state));return true;}catch{toast('本机存储不可用，本次会话可继续体验。');return false;}}
function art(i=0,alt='',cls=''){return `<img src="${Art.url(i)}" alt="${esc(alt||'原创示例分镜')}" class="${cls}" loading="lazy">`;}
const logo=()=>window.Cimora?Cimora.logo('/'):`<a class="logo" href="#/" aria-label="Cimora 首页"><span class="logo-mark">c<span>✦</span></span><strong>cimora</strong></a>`;
const link=(text,to,cls='')=>`<a href="#${to}" class="${cls}">${text}</a>`;
const button=(text,action,cls='button',extra='')=>`<button type="button" class="${cls}" data-act="${action}" ${extra}>${text}</button>`;
function toast(message){const n=document.createElement('div');n.className='site-toast';n.textContent=message;$('#site-toasts').append(n);setTimeout(()=>n.remove(),4200);}
function modal(title,body,footer='',wide=false){modalFocus=document.activeElement;$('#site-modal').hidden=false;$('#site-modal').innerHTML=`<section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="site-dialog-title"><header><h2 id="site-dialog-title">${esc(title)}</h2><button data-act="close" class="close" aria-label="关闭弹窗">×</button></header><div class="dialog-body">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section>`;requestAnimationFrame(()=>$('.dialog input,.dialog textarea,.dialog .primary,.dialog .close')?.focus());}
function close(){if($('#site-modal').hidden)return;$('#site-modal').hidden=true;$('#site-modal').innerHTML='';if(downloadPreviewURL){URL.revokeObjectURL(downloadPreviewURL);downloadPreviewURL=null;}if(modalFocus?.isConnected)modalFocus.focus();}
function download(data,name,type='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();if(blob.type==='image/png'){if(downloadPreviewURL)URL.revokeObjectURL(downloadPreviewURL);downloadPreviewURL=url;modal('示例 PNG 已合成',`<p>已发起下载。可以预览实际生成的图片，或再次保存。</p><img src="${url}" alt="${esc(name)}" style="max-height:55vh;width:100%;object-fit:contain;border-radius:7px">`,`<a class="button primary" href="${url}" download="${esc(name)}">保存 PNG 图片</a>`);}else setTimeout(()=>URL.revokeObjectURL(url),2000);toast('下载已发起：'+name);}
function route(path){if(S.beforeRoute&&!S.beforeRoute(path))return;close();if(location.hash==='#'+path)render();else location.hash=path;}
function project(id){return id?state.projects.find(p=>p.id===id):state.projects.find(p=>!p.archived);}
const id=prefix=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
function requireUser(pending){if(state.user)return false;state.pending=pending;save();route('/auth?return='+encodeURIComponent(location.hash.slice(1)||'/app'));return true;}
function completeAuth(){state.user={name:'故事创作者',email:'creator@example.test'};const pending=state.pending,back=context.params.get('return');state.pending=null;save();toast('已进入本地演示账户，没有发送登录信息。');if(pending?.action==='save-tool'){route('/tools/'+pending.tool);setTimeout(()=>S.tools.saveResult(pending.tool),0);}else if(pending?.path)route(pending.path);else route(back?.startsWith('/')?back:state.onboarded?'/app':'/onboarding');}
function publicHeader(){const p=context.path;return `<header class="public-header"><div class="nav-wrap">${logo()}<nav class="public-nav" aria-label="官网导航"><details class="nav-dropdown"><summary>产品 <span>⌄</span></summary><div>${link('产品总览 →','/product')}${link('条漫创作','/features/webtoon')}${link('动态漫制作','/features/motion-comic')}${link('工作室生产','/features/studio')}</div></details>${link('创作工具','/tools',p.startsWith('/tools')?'active':'')}${link('作品案例','/showcase',p.startsWith('/showcase')?'active':'')}${link('模板','/templates')}${link('定价','/pricing')}${link('创作指南','/resources')}</nav><div class="nav-actions">${state.user?link('我的工作空间 ↗','/app','button small'):link('登录','/auth','login-link')}${link('开始创作 ↗','/app/new','button primary small')}<button class="mobile-menu" data-act="menu" aria-label="打开导航" aria-expanded="false">☰</button></div></div></header>`;}
function footer(){return `<footer class="public-footer"><div class="footer-intro">${logo()}<p>让故事，在每一帧之间生长。</p><small>一致的角色，可编辑的创作，清晰的每一步。</small></div><div><h4>创作</h4>${link('条漫创作','/features/webtoon')}${link('动态漫制作','/features/motion-comic')}${link('工具中心','/tools')}${link('工作空间','/app')}</div><div><h4>灵感与支持</h4>${link('示例作品','/showcase')}${link('创作指南','/resources')}${link('帮助中心','/help')}${link('更新记录','/resources/updates')}</div><div><h4>关于使用</h4>${link('定价与用量','/pricing')}${link('隐私与数据','/legal/privacy')}${link('商业使用与版权','/legal/copyright')}${link('服务条款','/legal/terms')}</div><div class="footer-bottom"><span>© 2026 CIMORA · 全站交互原型</span><span>本机演示 · 生成、计费、发布均为模拟</span></div></footer>`;}
function appShell(content){return Cimora.shell(content,context);}
function empty(title,text,action='新建项目',to='/app/new'){return `<div class="empty"><span>✧</span><h3>${esc(title)}</h3><p>${esc(text)}</p>${link(action,to,'button primary')}</div>`;}
function crumbs(items){return `<nav class="crumbs" aria-label="面包屑">${items.map(([label,to])=>to?link(esc(label),to):`<span>${esc(label)}</span>`).join('<i>/</i>')}</nav>`;}
function sectionHead(kicker,title,desc='',extra=''){return `<div class="section-head"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${extra}</div>`;}
function faq(items=FrameData.faqs){return `<div class="faq-list">${items.map(([q,a])=>`<details><summary>${esc(q)}<span>＋</span></summary><p>${esc(a)}</p></details>`).join('')}</div>`;}
function render(){
 const raw=location.hash.slice(1)||'/';const legacy=['motion','script','assets','comic','export'];const [path,query='']=raw.split('?');context={path:path.startsWith('/')?path:'/'+path,parts:path.replace(/^\//,'').split('/'),params:new URLSearchParams(query)};S.context=context;
 if(legacy.includes(raw)){context.path='/app/editor/rain/ch1';context.parts=['app','editor','rain','ch1'];context.params=new URLSearchParams('step='+raw);}
 const isApp=context.path==='/app'||context.path.startsWith('/app/');if(!isApp&&window.CimoraPublicRoutes?.redirect(context))return;const editor=context.parts[0]==='app'&&context.parts[1]==='editor';document.body.className=editor?'editor-body':isApp?'app-body':'public-body';
 let content;if(context.path==='/auth'||context.path==='/onboarding')content=S.workspace.render(context);else if(context.parts[0]==='share')content=S.workspace.render(context);else if(editor)content=S.workspace.editor(context);else if(isApp)content=appShell(Cimora.route(context)??S.workspace.render(context));else if(context.parts[0]==='tools')content=publicHeader()+S.tools.render(context)+footer();else content=publicHeader()+(context.path==='/'?Cimora.publicHome():S.public.render(context))+footer();
 $('#site').innerHTML=content;document.title=(isApp?Cimora.pageTitle(context):(S.pageTitle||'创造你的宇宙'))+' · Cimora';if(!editor)window.scrollTo(0,0);S.tools?.afterRender?.(context);S.workspace?.afterRender?.(context);S.public?.afterRender?.(context);Cimora.afterRender(context);
}
function start(){window.addEventListener('hashchange',()=>{if(S.beforeHashChange&&!S.beforeHashChange())return;close();render();});document.addEventListener('click',event=>{const el=event.target.closest('[data-act]');if(!el)return;const action=el.dataset.act;if(action==='close')close();else if(action==='menu'){const header=$('.public-header');header.classList.toggle('menu-open');el.setAttribute('aria-expanded',header.classList.contains('menu-open'));}else if(action==='auth')completeAuth();else if(action==='logout'){state.user=null;save();render();toast('已退出本地演示账户。');}else if(action==='support')modal('告诉我们你的问题',`<form data-form="support"><label>问题类型<select name="kind"><option>使用问题</option><option>原型反馈</option><option>版权与数据</option></select></label><label>描述<textarea name="message" required minlength="5" placeholder="描述你遇到的问题…"></textarea></label><p class="muted">仅保存反馈草稿，不发送给任何人。</p><button class="button primary full">保存本机反馈</button></form>`);else if(!S.tools.onClick?.(action,el,event)&&!S.workspace.onClick?.(action,el,event))S.public.onClick?.(action,el,event);});
 document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();if(f.dataset.form==='support'){download(Object.fromEntries(new FormData(f)),'framein-feedback-draft.json');close();}else if(!S.tools.onSubmit?.(f))S.workspace.onSubmit?.(f);});
 document.addEventListener('input',e=>{S.tools.onInput?.(e.target);S.workspace.onInput?.(e.target);S.public.onInput?.(e.target);});document.addEventListener('change',e=>{S.tools.onChange?.(e.target);S.workspace.onChange?.(e.target);S.public.onChange?.(e.target);});
 $('#site-modal').addEventListener('click',e=>{if(e.target===$('#site-modal'))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();$('.menu-open')?.classList.remove('menu-open');}if(e.key==='Tab'&&!$('#site-modal').hidden){const f=$$('button:not(:disabled),input,select,textarea,a[href]',$('.dialog')).filter(n=>n.getClientRects().length);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus();}}});
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('#studio-frame')?.contentWindow)return;if(e.data?.type==='framein:navigate'&&typeof e.data.path==='string'&&e.data.path.startsWith('/'))route(e.data.path);if(e.data?.type==='framein:export'&&e.data.record){const r=e.data.record;if(!state.exports.some(x=>x.id===r.id)){state.exports.unshift(r);save();}}});render();}
const S={$, $$,esc,state,ui,context,save,art,logo,link,button,toast,modal,close,download,route,project,id,requireUser,completeAuth,empty,crumbs,sectionHead,faq,render,start,public:{},tools:{},workspace:{},pageTitle:''};return S;
})();
